<?php echo DB::table('ventas_joyeria_general as g')->join('ventas_joyeria_detalle as d', 'g.id', '=', 'd.venta_id')->leftJoin('movimientos_cajas as m', function($join) { $join->on('m.referencia_id', '=', 'g.id')->where('m.tipo', 'SALIDA')->where('m.observaciones', 'like', 'Compra de Joyer%'); })->where('g.id', 7)->select('g.id', 'm.id as m_id', 'm.observaciones')->get()->toJson();
